1	import type { PluginPasses } from "../../config/index.ts";
2	import convertSourceMap from "convert-source-map";
3	import type { GeneratorResult } from "@babel/generator";
4	import generate from "@babel/generator";
5	
6	import type File from "./file.ts";
7	
8	export default function generateCode(
9	  pluginPasses: PluginPasses,
10	  file: File,
11	): {
12	  outputCode: string;
13	  outputMap: GeneratorResult["map"] | null;
14	} {
15	  const { opts, ast, code, inputMap } = file;
16	  const generatorOpts = opts.generatorOpts!;
17	
18	  generatorOpts.inputSourceMap = inputMap?.toObject();
19	
20	  const results = [];
21	  for (const plugins of pluginPasses) {
22	    for (const plugin of plugins) {
23	      const { generatorOverride } = plugin;
24	      if (generatorOverride) {
25	        const result = generatorOverride(ast, generatorOpts, code, generate);
26	
27	        if (result !== undefined) results.push(result);
28	      }
29	    }
30	  }
31	
32	  let result;
33	  if (results.length === 0) {
34	    result = generate(ast, generatorOpts, code);
35	  } else if (results.length === 1) {
36	    result = results[0];
37	
38	    // @ts-expect-error check if generatorOverride returned a promise
39	    if (typeof result.then === "function") {
40	      throw new Error(
41	        `You appear to be using an async codegen plugin, ` +
42	          `which your current version of Babel does not support. ` +
43	          `If you're using a published plugin, ` +
44	          `you may need to upgrade your @babel/core version.`,
45	      );
46	    }
47	  } else {
48	    throw new Error("More than one plugin attempted to override codegen.");
49	  }
50	
51	  let { code: outputCode } = result;
52	
53	  let outputMap = result.map;
54	
55	  if (opts.sourceMaps === "inline" || opts.sourceMaps === "both") {
56	    outputCode += "\n" + convertSourceMap.fromObject(outputMap).toComment();
57	  }
58	
59	  if (opts.sourceMaps === "inline") {
60	    outputMap = null;
61	  }
62	
63	  return { outputCode, outputMap };
64	}
