45	      sourceRoot?: string;
46	      inputSourceMap?: SourceMapInput;
47	    },
48	    code: string | Record<string, string> | null | undefined,
49	  ) {
50	    const map = (this._map = new GenMapping({ sourceRoot: opts.sourceRoot }));
51	    this._sourceFileName = opts.sourceFileName?.replace(/\\/g, "/");
52	    this._rawMappings = undefined;
53	
54	    if (opts.inputSourceMap) {
55	      this._inputMap = new TraceMap(opts.inputSourceMap);
56	      const resolvedSources = this._inputMap.resolvedSources;
57	      if (resolvedSources.length) {
