100	   */
101	
102	  mark(
103	    generated: { line: number; column: number },
104	    line?: number,
105	    column?: number,
106	    identifierName?: string | null,
107	    identifierNamePos?: { line: number; column: number },
108	    filename?: string | null,
109	  ) {
110	    this._rawMappings = undefined;
111	
112	    let originalMapping: OriginalMapping | InvalidOriginalMapping | undefined;
113	
114	    if (line != null) {
115	      if (this._inputMap) {
116	        // This is the lookup for this mark
117	        originalMapping = originalPositionFor(this._inputMap, {
118	          line,
119	          column: column!,
120	        });
121	
122	        // If the we found a name, nothing else needs to be done
123	        // Maybe we're marking a `(` and the input map already had a name attached there,
124	        // or we're marking a `(` and the sourcemap spanned a `foo(`,
125	        // or we're marking an identifier, etc.
126	        if (!originalMapping.name && identifierNamePos) {
